 Context c;
 @Before public void reset(){c=RuntimeEnvironment.getApplication();for(String n:new String[]{"project_dark_f5m_v1","project_dark_skill_book_v1","project_dark_skill_test_v1"})c.getSharedPreferences(n,0).edit().clear().commit();F5mSaveStore.install(c);UiTheme.install(c);}
 static WorldRuntimeAdapter adapter(RuntimeState s){PoteCampaignMapDef d=PoteCampaignMapDef.forId(s.currentMapId());return new WorldRuntimeAdapter(s,960,540,d.minX,d.maxX,d.minY,d.maxY,d.navigationTiles(),d.obstacles(),true);}
 @Test public void lobbyTwoCorridorsAndEveryDoorHaveWalkableConnectedRoutes(){
  for(String id:new String[]{HorrorCastleGeometry.LOBBY,HorrorCastleGeometry.FIRST,HorrorCastleGeometry.SECOND}){RuntimeState s=new RuntimeState();s.enterCampaignMap(id,false);assertTrue(s.monsters().isEmpty());WorldRuntimeAdapter w=adapter(s);for(HorrorCastleGeometry.Door d:HorrorCastleGeometry.doors(id)){assertNotNull(d.label,PoteCampaignMapDef.forId(id).exactCenter(d.x,d.y));assertTrue(d.label,CampaignNavigationTest.walk(w,w.requestGroundWorld(d.x,d.y)));}assertTrue(PoteCampaignMapDef.forId(id).terrainBlocked(170,100,10));}
 }
 @Test public void allFifteenRoomsSpawnFifteenSeparatedRandomActorsAndNeverRespawn(){
  Set<Integer> types=new HashSet<>();Set<String> elements=new HashSet<>();for(int n=1;n<=HorrorCastleGeometry.ROOM_COUNT;n++){RuntimeState s=new RuntimeState();s.horror().start();s.enterCampaignMap(HorrorCastleGeometry.roomId(n),false);assertEquals(15,s.monsters().size());Set<String> ids=new HashSet<>();for(RuntimeState.Monster m:s.monsters()){assertTrue(ids.add(m.id));assertFalse(s.blocked(m.x,m.y));assertTrue(s.isMonsterTileCenter(m.x,m.y));assertTrue(Float.isInfinite(m.respawnSeconds));types.add(HorrorCastleMonsters.type(m.id));AbelCombatProfile profile=AbelCombatProfile.forId(m.id);assertNotNull(profile);elements.add(profile.element);assertTrue(m.maxHp>=80000&&m.maxHp<=140000);for(RuntimeState.Monster other:s.monsters())if(other!=m)assertTrue(Math.hypot(m.x-other.x,m.y-other.y)>=63.9);s.damage(m,m.hp);}s.tick(100000);for(RuntimeState.Monster m:s.monsters())assertFalse(m.alive);}
  assertEquals(10,types.size());assertEquals(4,elements.size());
 }
 @Test public void clearOnlyAfterLastKillVisitsAllFifteenThenStartsFreshLap(){RuntimeState s=new RuntimeState();s.enterCampaignMap(HorrorCastleGeometry.roomId(1),false);for(int n=1;n<=HorrorCastleGeometry.ROOM_COUNT;n++){String current=HorrorCastleGeometry.roomId(n);assertEquals(current,s.currentMapId());for(int i=0;i<14;i++)s.damage(s.monsters().get(i),Integer.MAX_VALUE);assertFalse(s.horror().clear(current,s.monsters()));s.damage(s.monsters().get(14),Integer.MAX_VALUE);assertTrue(s.horror().clear(current,s.monsters()));String next=s.horror().next(current);assertEquals(n==HorrorCastleGeometry.ROOM_COUNT?HorrorCastleGeometry.roomId(1):HorrorCastleGeometry.roomId(n+1),next);s.enterCampaignMap(next,false);}assertEquals(0,s.horror().clearedMask());assertEquals(15,s.monsters().size());}
 @Test public void sharedCombatAppliesMasterRewardExactlyOnce()throws Exception{RuntimeState s=new RuntimeState();s.enterCampaignMap(HorrorCastleGeometry.roomId(1),false);RuntimeState.Monster m=s.monsters().get(0);s.damage(m,m.hp-1);s.player().x=m.x-32;s.player().y=m.y-16;RuntimeCombatSession session=new RuntimeCombatSession(s,(a,b)->true,(a,b)->true,a->true);long before=CampaignProgress.earnedExp(s.rpg());int receipts=s.rpg().rewardHistory().size();assertTrue(session.submitPlayerBasicAttack(m.id).combat.accepted());for(int i=0;i<40&&m.alive;i++){session.tick(.05f);s.tick(.05f);}assertFalse(m.alive);s.rpg().consumeCombat(s.ledger().snapshot(),s);assertEquals(before+HorrorCastleMonsters.EXP[HorrorCastleMonsters.type(m.id)],CampaignProgress.earnedExp(s.rpg()));assertEquals(receipts+1,s.rpg().rewardHistory().size());s.rpg().consumeCombat(s.ledger().snapshot(),s);assertEquals(receipts+1,s.rpg().rewardHistory().size());}
 @Test public void nativeMillesCardBothCorridorsRoomProgressAndSavedDeathsSurviveRestart()throws Exception{
  GameView v=new GameView(c);v.layout(0,0,960,540);RuntimeState s=ItemWindowReferenceTest.field(v,"state");RuntimeState.Npc npc=s.npcs().stream().filter(n->n.id.equals("pote_travel_guide")).findFirst().get();s.player().x=npc.x;s.player().y=npc.y;InteractionController interaction=ItemWindowReferenceTest.field(v,"interaction");assertEquals(InteractionController.TickResult.DIALOG_OPENED,interaction.request(s,npc));RectF card=TownTravelWindow.cardFor(WorldDef.ID,HorrorCastleGeometry.LOBBY);assertNotNull(card);render(v,"travel.png");ItemWindowReferenceTest.tap(v,card.centerX(),card.centerY());assertEquals(HorrorCastleGeometry.LOBBY,s.currentMapId());render(v,"lobby.png");
  Method change=GameView.class.getDeclaredMethod("changeCampaignMap",String.class,boolean.class);change.setAccessible(true);Method gate=GameView.class.getDeclaredMethod("checkCampaignGate");gate.setAccessible(true);
  for(String corridor:new String[]{HorrorCastleGeometry.FIRST,HorrorCastleGeometry.SECOND}){change.invoke(v,HorrorCastleGeometry.LOBBY,false);HorrorCastleGeometry.Door entry=HorrorCastleGeometry.doors(HorrorCastleGeometry.LOBBY).stream().filter(d->d.destination.equals(corridor)).findFirst().get();s.player().x=entry.x;s.player().y=entry.y;assertEquals(true,gate.invoke(v));assertEquals(corridor,s.currentMapId());render(v,corridor.endsWith("1")?"corridor-1.png":"corridor-2.png");HorrorCastleGeometry.Door door=HorrorCastleGeometry.doors(corridor).stream().filter(d->d.destination.equals(HorrorCastleGeometry.roomId(1))).findFirst().get();s.player().x=door.x;s.player().y=door.y;assertEquals(true,gate.invoke(v));assertEquals(HorrorCastleGeometry.roomId(1),s.currentMapId());}
  Method update=GameView.class.getDeclaredMethod("updatePoteField",float.class);update.setAccessible(true);
  for(int n=1;n<=HorrorCastleGeometry.ROOM_COUNT;n++){assertEquals(HorrorCastleGeometry.roomId(n),s.currentMapId());render(v,String.format(Locale.ROOT,"room-%02d.png",n));for(RuntimeState.Monster m:s.monsters())s.damage(m,Integer.MAX_VALUE);update.invoke(v,.01f);assertEquals(n==HorrorCastleGeometry.ROOM_COUNT?HorrorCastleGeometry.roomId(1):HorrorCastleGeometry.roomId(n+1),s.currentMapId());}
  s.horror().start();change.invoke(v,HorrorCastleGeometry.roomId(4),false);assertEquals(15,s.monsters().stream().filter(m->m.alive).count());RuntimeState.Monster dead=s.monsters().get(0),hurt=s.monsters().get(1);s.damage(dead,Integer.MAX_VALUE);s.damage(hurt,111);String deadId=dead.id,hurtId=hurt.id;int hp=hurt.hp;assertTrue(hp>0&&hp<hurt.maxHp);assertEquals(14,s.monsters().stream().filter(m->m.alive).count());long seed=s.horror().seed();s.tick(.01f);assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(c);GameView restarted=new GameView(c);restarted.layout(0,0,960,540);RuntimeState restored=ItemWindowReferenceTest.field(restarted,"state");assertEquals(HorrorCastleGeometry.roomId(4),restored.currentMapId());assertEquals(seed,restored.horror().seed());assertEquals(14,restored.monsters().stream().filter(m->m.alive).count());assertFalse(restored.monsters().stream().filter(m->m.id.equals(deadId)).findFirst().get().alive);assertEquals(hp,restored.monsters().stream().filter(m->m.id.equals(hurtId)).findFirst().get().hp);restored.tick(10000);assertEquals(14,restored.monsters().stream().filter(m->m.alive).count());assertFalse(restored.monsters().stream().filter(m->m.id.equals(deadId)).findFirst().get().alive);render(restarted,"restart.png");
 }
 @Test public void warmBackgroundCacheStaysBoundedAcrossTwelveTripsAndAllSourcePosesExist()throws Exception{HorrorCastleRenderer renderer=new HorrorCastleRenderer(c);for(int i=0;i<12;i++){String id=HorrorCastleGeometry.roomId(i%HorrorCastleGeometry.ROOM_COUNT+1);renderer.prepare(id);int builds=renderer.backgroundBuilds();RuntimeState runtime=new RuntimeState();runtime.enterCampaignMap(id,false);WorldRuntimeAdapter world=adapter(runtime);Bitmap target=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);renderer.draw(new Canvas(target),world,Collections.emptyList());assertTrue(renderer.backgroundBytes()>0);assertTrue(renderer.backgroundBytes()<=8652800);int bytes=renderer.backgroundBytes();renderer.draw(new Canvas(target),world,Collections.emptyList());renderer.prepare(id);assertEquals(builds,renderer.backgroundBuilds());assertEquals(bytes,renderer.backgroundBytes());}renderer.releaseFloor();assertEquals(0,renderer.backgroundBytes());for(int t=0;t<10;t++)try(InputStream in=c.getAssets().open("horror-v180/monster_"+t+".png")){Bitmap b=BitmapFactory.decodeStream(in);assertEquals(640,b.getWidth());assertEquals(1280,b.getHeight());for(int row=0;row<10;row++)for(int col=0;col<4;col++){boolean alpha=false;for(int y=row*128;y<(row+1)*128&&!alpha;y++)for(int x=col*160;x<(col+1)*160;x++)if(Color.alpha(b.getPixel(x,y))>0){alpha=true;break;}assertTrue(t+" "+row+" "+col,alpha);}}}
 @Test public void recoveredMapsUseOriginalCellsAndNeverCertifyMissingRooms(){
  assertEquals(6002,HorrorCastleGeometry.original(HorrorCastleGeometry.LOBBY).sourceId);
  assertEquals(50,HorrorCastleGeometry.columns(HorrorCastleGeometry.LOBBY));assertEquals(20,HorrorCastleGeometry.rows(HorrorCastleGeometry.LOBBY));
  for(int n=1;n<=11;n++){String id=HorrorCastleGeometry.roomId(n);HorrorCastleOriginalData.Grid g=HorrorCastleGeometry.original(id);assertEquals(6400+n,g.sourceId);assertTrue(HorrorCastleGeometry.props(id).isEmpty());for(WorldMoveTargetController.TileCenter p:HorrorCastleGeometry.tiles(id,true)){int u=Math.round((p.y-160)/32+(p.x-800)/64),v=Math.round((p.y-160)/32-(p.x-800)/64);assertTrue(g.walkable(u,v));}WorldMoveTargetController.TileCenter e=HorrorCastleGeometry.entry(id);for(HorrorCastleGeometry.Door d:HorrorCastleGeometry.doors(id))assertTrue("arrival must not immediately exit "+id,Math.hypot(e.x-d.x,e.y-d.y)>22);}
  for(int n=12;n<=15;n++){HorrorCastleOriginalData.Grid g=HorrorCastleGeometry.original(HorrorCastleGeometry.roomId(n));assertNotNull(g);assertEquals("explicit adapted source id",0,g.sourceId);assertFalse(HorrorCastleReferenceRooms.pieces(HorrorCastleGeometry.roomId(n)).isEmpty());}
 }

 @Test public void originalReferenceLobbyThresholdsAndRinglessRoomDoors()throws Exception{
  List<HorrorCastleGeometry.Door> gates=HorrorCastleGeometry.doors(HorrorCastleGeometry.LOBBY);
  assertEquals(5,gates.stream().filter(d->d.label.equals("1층 서쪽 복도")).count());
  assertEquals(1,gates.stream().filter(d->d.label.equals("1층 동쪽 복도")).count());assertEquals(1,gates.stream().filter(d->d.label.equals("2층 중앙 복도")).count());
  for(int u=22;u<=26;u++){final int col=u;assertTrue(gates.stream().anyMatch(d->d.label.equals("1층 서쪽 복도")&&d.x==HorrorCastleGeometry.x(col,10)&&d.y==HorrorCastleGeometry.y(col,10)));}
  HorrorCastleGeometry.Door east=gates.stream().filter(d->d.label.equals("1층 동쪽 복도")).findFirst().get();
  assertEquals(HorrorCastleGeometry.x(46,3),east.markerX,.01);assertEquals(HorrorCastleGeometry.y(46,3),east.markerY,.01);
  assertTrue(HorrorCastleGeometry.inside(HorrorCastleGeometry.LOBBY,east.x,east.y,0));
  assertTrue(gates.stream().anyMatch(d->d.label.equals("2층 중앙 복도")&&d.x==HorrorCastleGeometry.x(18,1)&&d.y==HorrorCastleGeometry.y(18,1)));
  HorrorCastleOriginalData.Grid grid=HorrorCastleGeometry.original(HorrorCastleGeometry.LOBBY);int exits=0;
  for(int u=22;u<=26;u++)if(grid.walkable(u,19)){final int col=u;assertTrue(gates.stream().anyMatch(d->d.destination.equals("MILLES")&&d.x==HorrorCastleGeometry.x(col,19)&&d.y==HorrorCastleGeometry.y(col,19)));exits++;}
  assertEquals(5,exits);assertEquals(exits,gates.stream().filter(d->d.destination.equals("MILLES")).count());assertEquals(10,HorrorCastleGeometry.doors(HorrorCastleGeometry.FIRST).stream().filter(d->d.destination.equals(HorrorCastleGeometry.roomId(1))).count());
  for(String corridor:new String[]{HorrorCastleGeometry.FIRST,HorrorCastleGeometry.SECOND}){
   List<HorrorCastleGeometry.Door> doors=HorrorCastleGeometry.doors(corridor);
   assertEquals(4,doors.stream().filter(d->d.visiblePortal).count());
   Set<String> returns=new HashSet<>();
   for(HorrorCastleGeometry.Door d:doors){assertEquals(d.destination.equals(HorrorCastleGeometry.LOBBY),d.visiblePortal);if(d.visiblePortal)returns.add(d.x+","+d.y);}
   assertEquals(4,returns.size());
  }
  GameView v=new GameView(c);v.layout(0,0,960,540);java.lang.reflect.Field inside=GameView.class.getDeclaredField("inPoteField");inside.setAccessible(true);inside.setBoolean(v,true);Method change=GameView.class.getDeclaredMethod("changeCampaignMap",String.class,boolean.class);change.setAccessible(true);Method gate=GameView.class.getDeclaredMethod("checkCampaignGate");gate.setAccessible(true);RuntimeState state=ItemWindowReferenceTest.field(v,"state");
  // All seven lobby entry tiles must transition through the actual GameView gate handler.
  for(HorrorCastleGeometry.Door d:gates)if(!d.destination.equals("MILLES")){change.invoke(v,HorrorCastleGeometry.LOBBY,false);state.player().x=d.x;state.player().y=d.y;render(v,d.label.contains("서쪽")?"west-entrance.png":d.label.contains("동쪽")?"east-entrance.png":"upper-entrance.png");assertEquals(true,gate.invoke(v));assertEquals(d.destination,state.currentMapId());}
 }

 void render(GameView v,String name)throws Exception{WorldRuntimeAdapter w=ItemWindowReferenceTest.field(v,"poteFieldAdapter");if(w!=null){RuntimeState s=ItemWindowReferenceTest.field(v,"state");PoteCampaignMapDef d=PoteCampaignMapDef.forId(s.currentMapId());if(HorrorCastleGeometry.room(d.id)==0)w.snapCameraToPlayer();else w.camera().snapTo(HorrorCastleGeometry.x(HorrorCastleGeometry.columns(d.id)/2,HorrorCastleGeometry.rows(d.id)/2),HorrorCastleGeometry.y(HorrorCastleGeometry.columns(d.id)/2,HorrorCastleGeometry.rows(d.id)/2)-40);}Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));File folder=new File("build/reports/horror-v179");folder.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(folder,name))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
